53	/**
54	 * Helpers to create or cache a LottieComposition.
55	 * <p>
56	 * All factory methods take a cache key. The animation will be stored in an LRU cache for future use.
57	 * In-progress tasks will also be held so they can be returned for subsequent requests for the same
58	 * animation prior to the cache being populated.
59	 */
60	@SuppressWarnings({"WeakerAccess", "unused", "NullAway"})
61	public class LottieCompositionFactory {
62	
63	  /**
64	   * Keep a map of cache keys to in-progress tasks and return them for new requests.
65	   * Without this, simultaneous requests to parse a composition will trigger multiple parallel
66	   * parse tasks prior to the cache getting populated.
67	   */
68	  private static final Map<String, LottieTask<LottieComposition>> taskCache = new HashMap<>();
69	  private static final Set<LottieTaskIdleListener> taskIdleListeners = new HashSet<>();
70	
71	  /**
72	   * reference magic bytes for zip compressed files.
73	   * useful to determine if an InputStream is a zip file or not
74	   */
75	  private static final byte[] ZIP_MAGIC = new byte[]{0x50, 0x4b, 0x03, 0x04};
76	  private static final byte[] GZIP_MAGIC = new byte[]{0x1f, (byte) 0x8b, 0x08};
77	
