150	  public static LottieTask<LottieComposition> fromUrl(
151	      final Context context, final Looper uiLooper, final String url, @Nullable final String cacheKey) {
152	    return cache(uiLooper, cacheKey, () -> {
153	      LottieResult<LottieComposition> result = L.networkFetcher(context).fetchSync(context, url, cacheKey);
154	      if (cacheKey != null && result.getValue() != null) {
