261	  /**
262	   * Use this when you have an input stream but aren't sure if it is a json, zip, or gzip file.
263	   * This will read the file headers to see if it starts with the gzip or zip magic bytes.
264	   * @param context is optional and only needed if your zip file contains ttf or otf fonts. If yours doesn't, you may pass null.
265	   *                Embedded fonts may be .ttf or .otf files, can be in subdirectories, but must have the same name as the
266	   *                font family (fFamily) in your animation file.
267	   */
268	  public static LottieTask<LottieComposition> fromInputStream(@Nullable Context context, InputStream inputStream, @Nullable String cacheKey) {
269	    // App can override {@link Context#getMainLooper()} to support lottie view on per-window ui thread.
270	    final Looper uiLooper = context != null ? context.getMainLooper() : Looper.getMainLooper();
271	    // Prevent accidentally leaking an Activity.
272	    final Context appContext = context == null ? null : context.getApplicationContext();
273	    return cache(uiLooper, cacheKey, () -> fromInputStreamSync(appContext, inputStream, cacheKey), null);
