281	   *                font family (fFamily) in your animation file.
282	   */
283	  @WorkerThread
284	  public static LottieResult<LottieComposition> fromInputStreamSync(@Nullable Context context, InputStream inputStream, @Nullable String cacheKey) {
285	    final LottieComposition cachedComposition = cacheKey == null ? null : LottieCompositionCache.getInstance().get(cacheKey);
286	    if (cachedComposition != null) {
287	      return new LottieResult<>(cachedComposition);
288	    }
289	    try {
290	      BufferedSource source = Okio.buffer(source(inputStream));
291	      if (isZipCompressed(source)) {
292	        return fromZipStreamSync(context, new ZipInputStream(source.inputStream()), cacheKey);
293	      } else if (isGzipCompressed(source)) {
294	        return fromJsonInputStreamSync(new GZIPInputStream(source.inputStream()), cacheKey);
295	      }
296	      return fromJsonReaderSync(JsonReader.of(source), cacheKey);
297	    } catch (IOException e) {
298	      return new LottieResult<>(e);
299	    }
300	  }
