353	   * Parse an animation from raw/res. This is recommended over putting your animation in assets because
354	   * it uses a hard reference to R.
355	   * The resource id will be used as a cache key so future usages won't parse the json again.
356	   * Note: to correctly load dark mode (-night) resources, make sure you pass Activity as a context (instead of e.g. the application context).
357	   * The Activity won't be leaked.
358	   * <p>
359	   * Pass null as the cache key to skip caching.
360	   */
361	  @WorkerThread
362	  public static LottieResult<LottieComposition> fromRawResSync(Context context, @RawRes int rawRes, @Nullable String cacheKey) {
363	    final LottieComposition cachedComposition = cacheKey == null ? null : LottieCompositionCache.getInstance().get(cacheKey);
364	    if (cachedComposition != null) {
365	      return new LottieResult<>(cachedComposition);
366	    }
367	    try {
368	      BufferedSource source = Okio.buffer(source(context.getResources().openRawResource(rawRes)));
369	      if (isZipCompressed(source)) {
370	        return fromZipStreamSync(context, new ZipInputStream(source.inputStream()), cacheKey);
371	      } else if (isGzipCompressed(source)) {
372	        try {
373	          return fromJsonInputStreamSync(new GZIPInputStream(source.inputStream()), cacheKey);
374	        } catch (IOException e) {
375	          // This shouldn't happen because we check the header for magic bytes.
376	          return new LottieResult<>(e);
377	        }
378	      }
379	      return fromJsonReaderSync(JsonReader.of(source), cacheKey);
380	    } catch (Resources.NotFoundException e) {
381	      return new LottieResult<>(e);
382	    }
383	  }
