392	  private static boolean isNightMode(Context context) {
393	    int nightModeMasked = context.getResources().getConfiguration().uiMode & Configuration.UI_MODE_NIGHT_MASK;
394	    return nightModeMasked == Configuration.UI_MODE_NIGHT_YES;
