512	  private static LottieResult<LottieComposition> fromJsonReaderSyncInternal(
513	      JsonReader reader, @Nullable String cacheKey, boolean close) {
514	    try {
515	      final LottieComposition cachedComposition = cacheKey == null ? null : LottieCompositionCache.getInstance().get(cacheKey);
516	      if (cachedComposition != null) {
517	        return new LottieResult<>(cachedComposition);
518	      }
519	      LottieComposition composition = LottieCompositionMoshiParser.parse(reader);
520	      if (cacheKey != null) {
521	        LottieCompositionCache.getInstance().put(cacheKey, composition);
522	      }
523	      return new LottieResult<>(composition);
524	    } catch (Exception e) {
525	      return new LottieResult<>(e);
526	    } finally {
527	      if (close) {
528	        closeQuietly(reader);
529	      }
