634	  @WorkerThread
635	  private static LottieResult<LottieComposition> fromZipStreamSyncInternal(@Nullable Context context, ZipInputStream inputStream,
636	      @Nullable String cacheKey) {
637	    LottieComposition composition = null;
638	    Map<String, Bitmap> images = new HashMap<>();
639	    Map<String, Typeface> fonts = new HashMap<>();
640	
641	    try {
642	      final LottieComposition cachedComposition = cacheKey == null ? null : LottieCompositionCache.getInstance().get(cacheKey);
643	      if (cachedComposition != null) {
644	        return new LottieResult<>(cachedComposition);
645	      }
646	      ZipEntry entry = inputStream.getNextEntry();
647	      while (entry != null) {
648	        final String entryName = entry.getName();
649	        if (entryName.contains("__MACOSX")) {
650	          inputStream.closeEntry();
651	        } else if (entry.getName().equalsIgnoreCase("manifest.json")) { //ignore .lottie manifest
652	          inputStream.closeEntry();
653	        } else if (entry.getName().contains(".json")) {
654	          JsonReader reader = JsonReader.of(buffer(source(inputStream)));
655	          composition = LottieCompositionFactory.fromJsonReaderSyncInternal(reader, null, false).getValue();
656	        } else if (entryName.contains(".png") || entryName.contains(".webp") || entryName.contains(".jpg") || entryName.contains(".jpeg")) {
657	          String[] splitName = entryName.split("/");
658	          String name = splitName[splitName.length - 1];
659	          images.put(name, BitmapFactory.decodeStream(inputStream));
660	        } else if (entryName.contains(".ttf") || entryName.contains(".otf")) {
661	          String[] splitName = entryName.split("/");
662	          String fileName = splitName[splitName.length - 1];
663	          String fontFamily = fileName.split("\\.")[0];
664	
665	          if (context == null) {
666	            return new LottieResult<>(
667	                new IllegalStateException("Unable to extract font " + fontFamily + " please pass a non-null Context parameter"));
668	          }
669	
670	          File tempFile = new File(context.getCacheDir(), fileName);
671	          try (FileOutputStream fos = new FileOutputStream(tempFile)) {
672	            try (OutputStream output = new FileOutputStream(tempFile)) {
673	              byte[] buffer = new byte[4 * 1024];
674	              int read;
675	              while ((read = inputStream.read(buffer)) != -1) {
676	                output.write(buffer, 0, read);
677	              }
678	              output.flush();
679	            }
680	          } catch (Throwable e) {
681	            Logger.warning("Unable to save font " + fontFamily + " to the temporary file: " + fileName + ". ", e);
682	          }
683	          Typeface typeface = Typeface.createFromFile(tempFile);
684	          if (!tempFile.delete()) {
685	            Logger.warning("Failed to delete temp font file " + tempFile.getAbsolutePath() + ".");
686	          }
687	          fonts.put(fontFamily, typeface);
688	        } else {
689	          inputStream.closeEntry();
690	        }
691	
692	        entry = inputStream.getNextEntry();
693	      }
694	    } catch (IOException e) {
695	      return new LottieResult<>(e);
696	    }
697	
698	
699	    if (composition == null) {
700	      return new LottieResult<>(new IllegalArgumentException("Unable to parse composition"));
701	    }
702	
703	    for (Map.Entry<String, Bitmap> e : images.entrySet()) {
704	      LottieImageAsset imageAsset = findImageAssetForFileName(composition, e.getKey());
705	      if (imageAsset != null) {
706	        imageAsset.setBitmap(Utils.resizeBitmapIfNeeded(e.getValue(), imageAsset.getWidth(), imageAsset.getHeight()));
707	      }
708	    }
709	
710	    for (Map.Entry<String, Typeface> e : fonts.entrySet()) {
711	      boolean found = false;
712	      for (Font font : composition.getFonts().values()) {
713	        if (font.getFamily().equals(e.getKey())) {
714	          found = true;
715	          font.setTypeface(e.getValue());
716	        }
717	      }
718	      if (!found) {
719	        Logger.warning("Parsed font for " + e.getKey() + " however it was not found in the animation.");
720	      }
721	    }
722	
723	    if (images.isEmpty()) {
724	      for (Map.Entry<String, LottieImageAsset> entry : composition.getImages().entrySet()) {
725	        LottieImageAsset asset = entry.getValue();
726	        if (asset == null) {
727	          return null;
728	        }
729	        String filename = asset.getFileName();
730	        BitmapFactory.Options opts = new BitmapFactory.Options();
731	        opts.inScaled = true;
732	        opts.inDensity = 160;
733	
734	        if (filename.startsWith("data:") && filename.indexOf("base64,") > 0) {
735	          // Contents look like a base64 data URI, with the format data:image/png;base64,<data>.
736	          byte[] data;
737	          try {
738	            data = Base64.decode(filename.substring(filename.indexOf(',') + 1), Base64.DEFAULT);
739	          } catch (IllegalArgumentException e) {
740	            Logger.warning("data URL did not have correct base64 format.", e);
741	            return null;
742	          }
743	          Bitmap bitmap = BitmapFactory.decodeByteArray(data, 0, data.length, opts);
744	          if (bitmap != null) {
745	            bitmap = Utils.resizeBitmapIfNeeded(bitmap, asset.getWidth(), asset.getHeight());
746	            asset.setBitmap(bitmap);
747	          }
748	        }
749	      }
750	    }
751	
752	    if (cacheKey != null) {
753	      LottieCompositionCache.getInstance().put(cacheKey, composition);
754	    }
755	    return new LottieResult<>(composition);
756	  }
