758	  /**
759	   * Check if a given InputStream points to a .zip compressed file
760	   */
761	  private static Boolean isZipCompressed(BufferedSource inputSource) {
762	    return matchesMagicBytes(inputSource, ZIP_MAGIC);
763	  }
764	
765	  /**
766	   * Check if a given InputStream points to a .gzip compressed file
767	   */
768	  private static Boolean isGzipCompressed(BufferedSource inputSource) {
769	    return matchesMagicBytes(inputSource, GZIP_MAGIC);
770	  }
771	
772	  private static Boolean matchesMagicBytes(BufferedSource inputSource, byte[] magic) {
773	    try {
774	      BufferedSource peek = inputSource.peek();
775	      for (byte b : magic) {
776	        if (peek.readByte() != b) {
777	          return false;
778	        }
779	      }
780	      peek.close();
781	      return true;
782	    } catch (NoSuchMethodError e) {
783	      // This happens in the Android Studio layout preview.
784	      return false;
785	    } catch (Exception e) {
786	      Logger.error("Failed to check zip file header", e);
787	      return false;
788	    }
789	  }
