801	  private static LottieTask<LottieComposition> cache(
802	      @Nullable final String cacheKey, Callable<LottieResult<LottieComposition>> callable, @Nullable Runnable onCached) {
803	    return cache(Looper.getMainLooper(), cacheKey, callable, onCached);
804	  }
