806	  /**
807	   * First, check to see if there are any in-progress tasks associated with the cache key and return it if there is.
808	   * If not, create a new task for the callable.
809	   * Then, add the new task to the task cache and set up listeners so it gets cleared when done.
810	   */
811	  private static LottieTask<LottieComposition> cache(
812	      final Looper uiLooper, @Nullable final String cacheKey, Callable<LottieResult<LottieComposition>> callable, @Nullable Runnable onCached) {
813	    LottieTask<LottieComposition> task = null;
814	    final LottieComposition cachedComposition = cacheKey == null ? null : LottieCompositionCache.getInstance().get(cacheKey);
815	    if (cachedComposition != null) {
816	      task = new LottieTask<>(uiLooper, cachedComposition);
817	    }
818	    if (cacheKey != null && taskCache.containsKey(cacheKey)) {
819	      task = taskCache.get(cacheKey);
820	    }
821	    if (task != null) {
822	      if (onCached != null) {
823	        onCached.run();
824	      }
825	      return task;
826	    }
827	
828	    task = new LottieTask<>(uiLooper, callable);
829	    if (cacheKey != null) {
830	      AtomicBoolean resultAlreadyCalled = new AtomicBoolean(false);
831	      task.addListener(result -> {
832	        taskCache.remove(cacheKey);
833	        resultAlreadyCalled.set(true);
834	        if (taskCache.size() == 0) {
835	          notifyTaskCacheIdleListeners(true);
836	        }
837	      });
838	      task.addFailureListener(result -> {
839	        taskCache.remove(cacheKey);
840	        resultAlreadyCalled.set(true);
841	        if (taskCache.size() == 0) {
842	          notifyTaskCacheIdleListeners(true);
843	        }
844	      });
845	      // It is technically possible for the task to finish and for the listeners to get called
846	      // before this code runs. If this happens, the task will be put in taskCache but never removed.
847	      // This would require this thread to be sleeping at exactly this point in the code
848	      // for long enough for the task to finish and call the listeners. Unlikely but not impossible.
849	      if (!resultAlreadyCalled.get()) {
850	        taskCache.put(cacheKey, task);
851	        if (taskCache.size() == 1) {
852	          notifyTaskCacheIdleListeners(false);
853	        }
854	      }
855	    }
856	    return task;
857	  }
858	
859	  private static void notifyTaskCacheIdleListeners(boolean idle) {
860	    List<LottieTaskIdleListener> listeners = new ArrayList<>(taskIdleListeners);
861	    for (int i = 0; i < listeners.size(); i++) {
862	      listeners.get(i).onIdleChanged(idle);
863	    }
864	  }
865	}
