27	public class ContentGroup implements DrawingContent, PathContent,
28	    BaseKeyframeAnimation.AnimationListener, KeyPathElement {
29	
30	  private final OffscreenLayer.ComposeOp offscreenOp = new OffscreenLayer.ComposeOp();
31	  private final RectF offScreenRectF = new RectF();
32	  private final OffscreenLayer offscreenLayer = new OffscreenLayer();
33	
34	  private static List<Content> contentsFromModels(LottieDrawable drawable, LottieComposition composition, BaseLayer layer,
35	      List<ContentModel> contentModels) {
36	    List<Content> contents = new ArrayList<>(contentModels.size());
37	    for (int i = 0; i < contentModels.size(); i++) {
38	      Content content = contentModels.get(i).toContent(drawable, composition, layer);
39	      if (content != null) {
40	        contents.add(content);
41	      }
42	    }
43	    return contents;
44	  }
45	
46	  @Nullable static AnimatableTransform findTransform(List<ContentModel> contentModels) {
47	    for (int i = 0; i < contentModels.size(); i++) {
48	      ContentModel contentModel = contentModels.get(i);
49	      if (contentModel instanceof AnimatableTransform) {
50	        return (AnimatableTransform) contentModel;
51	      }
52	    }
53	    return null;
54	  }
55	
56	  private final Matrix matrix = new Matrix();
57	  private final Path path = new Path();
58	  private final RectF rect = new RectF();
59	
60	  private final String name;
61	  private final boolean hidden;
62	  private final List<Content> contents;
63	  private final LottieDrawable lottieDrawable;
64	  @Nullable private List<PathContent> pathContents;
65	  @Nullable private TransformKeyframeAnimation transformAnimation;
66	
67	  public ContentGroup(final LottieDrawable lottieDrawable, BaseLayer layer, ShapeGroup shapeGroup, LottieComposition composition) {
68	    this(lottieDrawable, layer, shapeGroup.getName(),
69	        shapeGroup.isHidden(), contentsFromModels(lottieDrawable, composition, layer, shapeGroup.getItems()),
70	        findTransform(shapeGroup.getItems()));
71	  }
72	
73	  ContentGroup(final LottieDrawable lottieDrawable, BaseLayer layer,
74	      String name, boolean hidden, List<Content> contents, @Nullable AnimatableTransform transform) {
75	    this.name = name;
76	    this.lottieDrawable = lottieDrawable;
77	    this.hidden = hidden;
78	    this.contents = contents;
79	
80	    if (transform != null) {
81	      transformAnimation = transform.createAnimation();
82	      transformAnimation.addAnimationsToLayer(layer);
83	      transformAnimation.addListener(this);
84	    }
85	
86	    List<GreedyContent> greedyContents = new ArrayList<>();
87	    for (int i = contents.size() - 1; i >= 0; i--) {
88	      Content content = contents.get(i);
89	      if (content instanceof GreedyContent) {
90	        greedyContents.add((GreedyContent) content);
91	      }
92	    }
93	
94	    for (int i = greedyContents.size() - 1; i >= 0; i--) {
95	      greedyContents.get(i).absorbContent(contents.listIterator(contents.size()));
96	    }
97	  }
98	
99	  @Override public void onValueChanged() {
100	    lottieDrawable.invalidateSelf();
101	  }
102	
103	  @Override public String getName() {
104	    return name;
105	  }
106	
107	  @Override public void setContents(List<Content> contentsBefore, List<Content> contentsAfter) {
108	    // Do nothing with contents after.
109	    List<Content> myContentsBefore = new ArrayList<>(contentsBefore.size() + contents.size());
110	    myContentsBefore.addAll(contentsBefore);
111	
112	    for (int i = contents.size() - 1; i >= 0; i--) {
113	      Content content = contents.get(i);
114	      content.setContents(myContentsBefore, contents.subList(0, i));
115	      myContentsBefore.add(content);
116	    }
117	  }
118	
119	  public List<Content> getContents() {
120	    return contents;
121	  }
122	
123	  List<PathContent> getPathList() {
124	    if (pathContents == null) {
125	      pathContents = new ArrayList<>();
126	      for (int i = 0; i < contents.size(); i++) {
127	        Content content = contents.get(i);
128	        if (content instanceof PathContent) {
129	          pathContents.add((PathContent) content);
130	        }
131	      }
132	    }
133	    return pathContents;
134	  }
135	
136	  Matrix getTransformationMatrix() {
137	    if (transformAnimation != null) {
138	      return transformAnimation.getMatrix();
139	    }
140	    matrix.reset();
141	    return matrix;
142	  }
143	
144	  @Override public Path getPath() {
145	    // TODO: cache this somehow.
146	    matrix.reset();
147	    if (transformAnimation != null) {
148	      matrix.set(transformAnimation.getMatrix());
149	    }
150	    path.reset();
151	    if (hidden) {
152	      return path;
153	    }
154	    for (int i = contents.size() - 1; i >= 0; i--) {
155	      Content content = contents.get(i);
156	      if (content instanceof PathContent) {
157	        path.addPath(((PathContent) content).getPath(), matrix);
158	      }
159	    }
160	    return path;
161	  }
162	
163	  @Override public void draw(Canvas canvas, Matrix parentMatrix, int parentAlpha, @Nullable DropShadow shadowToApply) {
164	    if (hidden) {
165	      return;
166	    }
167	    matrix.set(parentMatrix);
168	    int layerAlpha;
169	    if (transformAnimation != null) {
170	      matrix.preConcat(transformAnimation.getMatrix());
171	      int opacity = transformAnimation.getOpacity() == null ? 100 : transformAnimation.getOpacity().getValue();
172	      layerAlpha = (int) ((opacity / 100f * parentAlpha / 255f) * 255);
173	    } else {
174	      layerAlpha = parentAlpha;
175	    }
176	
177	    // Apply off-screen rendering only when needed in order to improve rendering performance.
178	    boolean isRenderingWithOffScreen =
179	        (lottieDrawable.isApplyingOpacityToLayersEnabled() && hasTwoOrMoreDrawableContent() && layerAlpha != 255) ||
180	        (shadowToApply != null && lottieDrawable.isApplyingShadowToLayersEnabled() && hasTwoOrMoreDrawableContent());
181	    int childAlpha = isRenderingWithOffScreen ? 255 : layerAlpha;
182	
183	    Canvas contentCanvas = canvas;
184	    if (isRenderingWithOffScreen) {
185	      offScreenRectF.set(0, 0, 0, 0);
186	      getBounds(offScreenRectF, parentMatrix, true);
187	      offscreenOp.alpha = layerAlpha;
188	      if (shadowToApply != null) {
189	        shadowToApply.applyTo(offscreenOp);
190	        shadowToApply = null; // Don't pass it to children - OffscreenLayer now takes care of this
191	      } else {
192	        offscreenOp.shadow = null;
193	      }
194	
195	      contentCanvas = offscreenLayer.start(canvas, offScreenRectF, offscreenOp);
196	    } else {
197	      if (shadowToApply != null) {
198	        shadowToApply = new DropShadow(shadowToApply);
199	        shadowToApply.multiplyOpacity(childAlpha);
200	      }
201	    }
202	
203	    for (int i = contents.size() - 1; i >= 0; i--) {
204	      Object content = contents.get(i);
205	      if (content instanceof DrawingContent) {
206	        ((DrawingContent) content).draw(contentCanvas, matrix, childAlpha, shadowToApply);
207	      }
208	    }
209	
210	    if (isRenderingWithOffScreen) {
211	      offscreenLayer.finish();
212	    }
213	  }
214	
215	  private boolean hasTwoOrMoreDrawableContent() {
216	    int drawableContentCount = 0;
217	    for (int i = 0; i < contents.size(); i++) {
218	      if (contents.get(i) instanceof DrawingContent) {
219	        drawableContentCount += 1;
220	        if (drawableContentCount >= 2) {
221	          return true;
222	        }
223	      }
224	    }
225	    return false;
226	  }
227	
228	  @Override public void getBounds(RectF outBounds, Matrix parentMatrix, boolean applyParents) {
229	    matrix.set(parentMatrix);
230	    if (transformAnimation != null) {
231	      matrix.preConcat(transformAnimation.getMatrix());
232	    }
233	    rect.set(0, 0, 0, 0);
234	    for (int i = contents.size() - 1; i >= 0; i--) {
235	      Content content = contents.get(i);
236	      if (content instanceof DrawingContent) {
237	        ((DrawingContent) content).getBounds(rect, matrix, applyParents);
238	        outBounds.union(rect);
239	      }
240	    }
241	  }
242	
243	  @Override public void resolveKeyPath(
244	      KeyPath keyPath, int depth, List<KeyPath> accumulator, KeyPath currentPartialKeyPath) {
245	    if (!keyPath.matches(getName(), depth) && !"__container".equals(getName())) {
246	      return;
247	    }
248	
249	    if (!"__container".equals(getName())) {
250	      currentPartialKeyPath = currentPartialKeyPath.addKey(getName());
251	
252	      if (keyPath.fullyResolvesTo(getName(), depth)) {
253	        accumulator.add(currentPartialKeyPath.resolve(this));
254	      }
255	    }
256	
257	    if (keyPath.propagateToChildren(getName(), depth)) {
258	      int newDepth = depth + keyPath.incrementDepthBy(getName(), depth);
259	      for (int i = 0; i < contents.size(); i++) {
260	        Content content = contents.get(i);
261	        if (content instanceof KeyPathElement) {
262	          KeyPathElement element = (KeyPathElement) content;
263	          element.resolveKeyPath(keyPath, newDepth, accumulator, currentPartialKeyPath);
264	        }
265	      }
266	    }
267	  }
268	
269	  @Override
270	  public <T> void addValueCallback(T property, @Nullable LottieValueCallback<T> callback) {
271	    if (transformAnimation != null) {
272	      transformAnimation.applyValueCallback(property, callback);
273	    }
274	  }
275	}
