1	package com.airbnb.lottie.animation.content;
2	
3	import android.graphics.Path;
4	import android.graphics.PointF;
5	
6	import androidx.annotation.Nullable;
7	
8	import com.airbnb.lottie.LottieDrawable;
9	import com.airbnb.lottie.LottieProperty;
10	import com.airbnb.lottie.animation.keyframe.BaseKeyframeAnimation;
11	import com.airbnb.lottie.model.KeyPath;
12	import com.airbnb.lottie.model.content.CircleShape;
13	import com.airbnb.lottie.model.content.ShapeTrimPath;
14	import com.airbnb.lottie.model.layer.BaseLayer;
15	import com.airbnb.lottie.utils.MiscUtils;
16	import com.airbnb.lottie.value.LottieValueCallback;
17	
18	import java.util.List;
19	
20	public class EllipseContent
21	    implements PathContent, BaseKeyframeAnimation.AnimationListener, KeyPathElementContent {
22	  private static final float ELLIPSE_CONTROL_POINT_PERCENTAGE = 0.55228f;
23	
24	  private final Path path = new Path();
25	
26	  private final String name;
27	  private final LottieDrawable lottieDrawable;
28	  private final BaseKeyframeAnimation<?, PointF> sizeAnimation;
29	  private final BaseKeyframeAnimation<?, PointF> positionAnimation;
30	  private final CircleShape circleShape;
31	
32	  private final CompoundTrimPathContent trimPaths = new CompoundTrimPathContent();
33	  private boolean isPathValid;
34	
35	  public EllipseContent(LottieDrawable lottieDrawable, BaseLayer layer, CircleShape circleShape) {
36	    name = circleShape.getName();
37	    this.lottieDrawable = lottieDrawable;
38	    sizeAnimation = circleShape.getSize().createAnimation();
39	    positionAnimation = circleShape.getPosition().createAnimation();
40	    this.circleShape = circleShape;
41	
42	    layer.addAnimation(sizeAnimation);
43	    layer.addAnimation(positionAnimation);
44	
45	    sizeAnimation.addUpdateListener(this);
46	    positionAnimation.addUpdateListener(this);
47	  }
48	
49	  @Override public void onValueChanged() {
50	    invalidate();
51	  }
52	
53	  private void invalidate() {
54	    isPathValid = false;
55	    lottieDrawable.invalidateSelf();
56	  }
57	
58	  @Override public void setContents(List<Content> contentsBefore, List<Content> contentsAfter) {
59	    for (int i = 0; i < contentsBefore.size(); i++) {
60	      Content content = contentsBefore.get(i);
61	      if (content instanceof TrimPathContent && ((TrimPathContent) content).getType() == ShapeTrimPath.Type.SIMULTANEOUSLY) {
62	        TrimPathContent trimPath = (TrimPathContent) content;
63	        trimPaths.addTrimPath(trimPath);
64	        trimPath.addListener(this);
65	      }
66	    }
67	  }
68	
69	  @Override public String getName() {
70	    return name;
71	  }
72	
73	  @Override public Path getPath() {
74	    if (isPathValid) {
75	      return path;
76	    }
77	
78	    path.reset();
79	
80	    if (circleShape.isHidden()) {
81	      isPathValid = true;
82	      return path;
83	    }
84	
85	    PointF size = sizeAnimation.getValue();
86	    float halfWidth = size.x / 2f;
87	    float halfHeight = size.y / 2f;
88	    // TODO: handle bounds
89	
90	    float cpW = halfWidth * ELLIPSE_CONTROL_POINT_PERCENTAGE;
91	    float cpH = halfHeight * ELLIPSE_CONTROL_POINT_PERCENTAGE;
92	
93	    path.reset();
94	    if (circleShape.isReversed()) {
95	      path.moveTo(0, -halfHeight);
96	      path.cubicTo(0 - cpW, -halfHeight, -halfWidth, 0 - cpH, -halfWidth, 0);
97	      path.cubicTo(-halfWidth, 0 + cpH, 0 - cpW, halfHeight, 0, halfHeight);
98	      path.cubicTo(0 + cpW, halfHeight, halfWidth, 0 + cpH, halfWidth, 0);
99	      path.cubicTo(halfWidth, 0 - cpH, 0 + cpW, -halfHeight, 0, -halfHeight);
100	    } else {
101	      path.moveTo(0, -halfHeight);
102	      path.cubicTo(0 + cpW, -halfHeight, halfWidth, 0 - cpH, halfWidth, 0);
103	      path.cubicTo(halfWidth, 0 + cpH, 0 + cpW, halfHeight, 0, halfHeight);
104	      path.cubicTo(0 - cpW, halfHeight, -halfWidth, 0 + cpH, -halfWidth, 0);
105	      path.cubicTo(-halfWidth, 0 - cpH, 0 - cpW, -halfHeight, 0, -halfHeight);
106	    }
107	
108	    PointF position = positionAnimation.getValue();
109	    path.offset(position.x, position.y);
110	
111	    path.close();
112	
113	    trimPaths.apply(path);
114	
115	    isPathValid = true;
116	    return path;
117	  }
118	
119	  @Override public void resolveKeyPath(
120	      KeyPath keyPath, int depth, List<KeyPath> accumulator, KeyPath currentPartialKeyPath) {
121	    MiscUtils.resolveKeyPath(keyPath, depth, accumulator, currentPartialKeyPath, this);
122	  }
123	
124	  @SuppressWarnings("unchecked")
125	  @Override
126	  public <T> void addValueCallback(T property, @Nullable LottieValueCallback<T> callback) {
127	    if (property == LottieProperty.ELLIPSE_SIZE) {
128	      sizeAnimation.setValueCallback((LottieValueCallback<PointF>) callback);
129	    } else if (property == LottieProperty.POSITION) {
130	      positionAnimation.setValueCallback((LottieValueCallback<PointF>) callback);
131	    }
132	  }
133	}
