49	
50	  public PolystarContent(LottieDrawable lottieDrawable, BaseLayer layer,
51	      PolystarShape polystarShape) {
52	    this.lottieDrawable = lottieDrawable;
53	
54	    name = polystarShape.getName();
55	    type = polystarShape.getType();
56	    hidden = polystarShape.isHidden();
57	    isReversed = polystarShape.isReversed();
58	    pointsAnimation = polystarShape.getPoints().createAnimation();
59	    positionAnimation = polystarShape.getPosition().createAnimation();
60	    rotationAnimation = polystarShape.getRotation().createAnimation();
61	    outerRadiusAnimation = polystarShape.getOuterRadius().createAnimation();
62	    outerRoundednessAnimation = polystarShape.getOuterRoundedness().createAnimation();
63	    if (type == PolystarShape.Type.STAR) {
64	      innerRadiusAnimation = polystarShape.getInnerRadius().createAnimation();
65	      innerRoundednessAnimation = polystarShape.getInnerRoundedness().createAnimation();
66	    } else {
67	      innerRadiusAnimation = null;
