146	  private void createStarPath() {
147	    float points = pointsAnimation.getValue();
148	    double currentAngle = rotationAnimation == null ? 0f : rotationAnimation.getValue();
149	    // Start at +y instead of +x
150	    currentAngle -= 90;
151	    // convert to radians
152	    currentAngle = Math.toRadians(currentAngle);
153	    // adjust current angle for partial points
154	    float anglePerPoint = (float) (2 * Math.PI / points);
155	    if (isReversed) {
156	      anglePerPoint *= -1;
157	    }
158	    float halfAnglePerPoint = anglePerPoint / 2.0f;
159	    float partialPointAmount = points - (int) points;
160	    if (partialPointAmount != 0) {
161	      currentAngle += halfAnglePerPoint * (1f - partialPointAmount);
162	    }
163	
164	    float outerRadius = outerRadiusAnimation.getValue();
165	    //noinspection ConstantConditions
166	    float innerRadius = innerRadiusAnimation.getValue();
167	
168	    float innerRoundedness = 0f;
169	    if (innerRoundednessAnimation != null) {
170	      innerRoundedness = innerRoundednessAnimation.getValue() / 100f;
171	    }
172	    float outerRoundedness = 0f;
173	    if (outerRoundednessAnimation != null) {
174	      outerRoundedness = outerRoundednessAnimation.getValue() / 100f;
175	    }
176	
177	    float x;
178	    float y;
179	    float previousX;
180	    float previousY;
181	    float partialPointRadius = 0;
182	    if (partialPointAmount != 0) {
183	      partialPointRadius = innerRadius + partialPointAmount * (outerRadius - innerRadius);
184	      x = (float) (partialPointRadius * Math.cos(currentAngle));
185	      y = (float) (partialPointRadius * Math.sin(currentAngle));
186	      path.moveTo(x, y);
187	      currentAngle += anglePerPoint * partialPointAmount / 2f;
188	    } else {
189	      x = (float) (outerRadius * Math.cos(currentAngle));
190	      y = (float) (outerRadius * Math.sin(currentAngle));
191	      path.moveTo(x, y);
192	      currentAngle += halfAnglePerPoint;
193	    }
194	
195	    // True means the line will go to outer radius. False means inner radius.
196	    boolean longSegment = false;
197	    double numPoints = Math.ceil(points) * 2;
198	    for (int i = 0; i < numPoints; i++) {
199	      float radius = longSegment ? outerRadius : innerRadius;
200	      float dTheta = halfAnglePerPoint;
201	      if (partialPointRadius != 0 && i == numPoints - 2) {
202	        dTheta = anglePerPoint * partialPointAmount / 2f;
203	      }
204	      if (partialPointRadius != 0 && i == numPoints - 1) {
205	        radius = partialPointRadius;
206	      }
207	      previousX = x;
208	      previousY = y;
209	      x = (float) (radius * Math.cos(currentAngle));
210	      y = (float) (radius * Math.sin(currentAngle));
211	
212	      if (innerRoundedness == 0 && outerRoundedness == 0) {
213	        path.lineTo(x, y);
214	      } else {
215	        float cp1Theta = (float) (Math.atan2(previousY, previousX) - Math.PI / 2f);
216	        float cp1Dx = (float) Math.cos(cp1Theta);
217	        float cp1Dy = (float) Math.sin(cp1Theta);
218	
219	        float cp2Theta = (float) (Math.atan2(y, x) - Math.PI / 2f);
220	        float cp2Dx = (float) Math.cos(cp2Theta);
221	        float cp2Dy = (float) Math.sin(cp2Theta);
222	
223	        float cp1Roundedness = longSegment ? innerRoundedness : outerRoundedness;
224	        float cp2Roundedness = longSegment ? outerRoundedness : innerRoundedness;
225	        float cp1Radius = longSegment ? innerRadius : outerRadius;
226	        float cp2Radius = longSegment ? outerRadius : innerRadius;
227	
228	        float cp1x = cp1Radius * cp1Roundedness * POLYSTAR_MAGIC_NUMBER * cp1Dx;
229	        float cp1y = cp1Radius * cp1Roundedness * POLYSTAR_MAGIC_NUMBER * cp1Dy;
230	        float cp2x = cp2Radius * cp2Roundedness * POLYSTAR_MAGIC_NUMBER * cp2Dx;
231	        float cp2y = cp2Radius * cp2Roundedness * POLYSTAR_MAGIC_NUMBER * cp2Dy;
232	        if (partialPointAmount != 0) {
233	          if (i == 0) {
234	            cp1x *= partialPointAmount;
235	            cp1y *= partialPointAmount;
236	          } else if (i == numPoints - 1) {
237	            cp2x *= partialPointAmount;
238	            cp2y *= partialPointAmount;
239	          }
240	        }
241	
242	        path.cubicTo(previousX - cp1x, previousY - cp1y, x + cp2x, y + cp2y, x, y);
243	      }
244	
245	      currentAngle += dTheta;
246	      longSegment = !longSegment;
247	    }
248	
249	
250	    PointF position = positionAnimation.getValue();
251	    path.offset(position.x, position.y);
252	    path.close();
253	  }
254	
255	  private void createPolygonPath() {
256	    int points = (int) Math.floor(pointsAnimation.getValue());
257	    double currentAngle = rotationAnimation == null ? 0f : rotationAnimation.getValue();
258	    // Start at +y instead of +x
259	    currentAngle -= 90;
260	    // convert to radians
261	    currentAngle = Math.toRadians(currentAngle);
262	    // adjust current angle for partial points
263	    float anglePerPoint = (float) (2 * Math.PI / points);
264	
265	    float roundedness = outerRoundednessAnimation.getValue() / 100f;
266	    float radius = outerRadiusAnimation.getValue();
267	    float x;
268	    float y;
269	    float previousX;
270	    float previousY;
271	    x = (float) (radius * Math.cos(currentAngle));
272	    y = (float) (radius * Math.sin(currentAngle));
273	    path.moveTo(x, y);
274	    currentAngle += anglePerPoint;
275	
276	    double numPoints = Math.ceil(points);
277	    for (int i = 0; i < numPoints; i++) {
278	      previousX = x;
279	      previousY = y;
280	      x = (float) (radius * Math.cos(currentAngle));
281	      y = (float) (radius * Math.sin(currentAngle));
282	
283	      if (roundedness != 0) {
284	        float cp1Theta = (float) (Math.atan2(previousY, previousX) - Math.PI / 2f);
285	        float cp1Dx = (float) Math.cos(cp1Theta);
286	        float cp1Dy = (float) Math.sin(cp1Theta);
287	
288	        float cp2Theta = (float) (Math.atan2(y, x) - Math.PI / 2f);
289	        float cp2Dx = (float) Math.cos(cp2Theta);
290	        float cp2Dy = (float) Math.sin(cp2Theta);
291	
292	        float cp1x = radius * roundedness * POLYGON_MAGIC_NUMBER * cp1Dx;
293	        float cp1y = radius * roundedness * POLYGON_MAGIC_NUMBER * cp1Dy;
294	        float cp2x = radius * roundedness * POLYGON_MAGIC_NUMBER * cp2Dx;
295	        float cp2y = radius * roundedness * POLYGON_MAGIC_NUMBER * cp2Dy;
296	
297	        if (i == numPoints - 1) {
298	          // When there is a huge stroke, it will flash if the path ends where it starts.
299	          // We want the final bezier curve to end *slightly* before the start.
300	          // The close() call at the end will complete the polystar.
301	          // https://github.com/airbnb/lottie-android/issues/2329
302	          lastSegmentPath.reset();
303	          lastSegmentPath.moveTo(previousX, previousY);
304	          lastSegmentPath.cubicTo(previousX - cp1x, previousY - cp1y, x + cp2x, y + cp2y, x, y);
305	          lastSegmentPathMeasure.setPath(lastSegmentPath, false);
306	          lastSegmentPathMeasure.getPosTan(lastSegmentPathMeasure.getLength() * 0.9999f, lastSegmentPosition, null);
307	          path.cubicTo(previousX - cp1x, previousY - cp1y, x + cp2x, y + cp2y,lastSegmentPosition[0], lastSegmentPosition[1]);
308	        } else {
309	          path.cubicTo(previousX - cp1x, previousY - cp1y, x + cp2x, y + cp2y, x, y);
310	        }
311	      } else {
312	        if (i == numPoints - 1) {
313	          // When there is a huge stroke, it will flash if the path ends where it starts.
314	          // The close() call should make the path effectively equivalent.
315	          // https://github.com/airbnb/lottie-android/issues/2329
316	          continue;
317	        }
318	        path.lineTo(x, y);
319	      }
320	
321	      currentAngle += anglePerPoint;
322	    }
323	
324	    PointF position = positionAnimation.getValue();
325	    path.offset(position.x, position.y);
326	    path.close();
327	  }
328	
329	  @Override public void resolveKeyPath(
330	      KeyPath keyPath, int depth, List<KeyPath> accumulator, KeyPath currentPartialKeyPath) {
331	    MiscUtils.resolveKeyPath(keyPath, depth, accumulator, currentPartialKeyPath, this);
332	  }
333	
334	  @SuppressWarnings("unchecked")
335	  @Override
336	  public <T> void addValueCallback(T property, @Nullable LottieValueCallback<T> callback) {
337	    if (property == LottieProperty.POLYSTAR_POINTS) {
338	      pointsAnimation.setValueCallback((LottieValueCallback<Float>) callback);
339	    } else if (property == LottieProperty.POLYSTAR_ROTATION) {
340	      rotationAnimation.setValueCallback((LottieValueCallback<Float>) callback);
341	    } else if (property == LottieProperty.POSITION) {
342	      positionAnimation.setValueCallback((LottieValueCallback<PointF>) callback);
343	    } else if (property == LottieProperty.POLYSTAR_INNER_RADIUS && innerRadiusAnimation != null) {
344	      innerRadiusAnimation.setValueCallback((LottieValueCallback<Float>) callback);
345	    } else if (property == LottieProperty.POLYSTAR_OUTER_RADIUS) {
346	      outerRadiusAnimation.setValueCallback((LottieValueCallback<Float>) callback);
347	    } else if (property == LottieProperty.POLYSTAR_INNER_ROUNDEDNESS && innerRoundednessAnimation != null) {
348	      innerRoundednessAnimation.setValueCallback((LottieValueCallback<Float>) callback);
349	    } else if (property == LottieProperty.POLYSTAR_OUTER_ROUNDEDNESS) {
350	      outerRoundednessAnimation.setValueCallback((LottieValueCallback<Float>) callback);
351	    }
352	  }
