30	  private static final JsonReader.Options NAMES = JsonReader.Options.of(
31	      "nm",     // 0
32	      "ind",    // 1
33	      "refId",  // 2
34	      "ty",     // 3
35	      "parent", // 4
36	      "sw",     // 5
37	      "sh",     // 6
38	      "sc",     // 7
39	      "ks",     // 8
40	      "tt",     // 9
41	      "masksProperties", // 10
42	      "shapes", // 11
43	      "t",  // 12
44	      "ef", // 13
45	      "sr", // 14
46	      "st", // 15
47	      "w",  // 16
48	      "h",  // 17
49	      "ip", // 18
50	      "op", // 19
51	      "tm", // 20
52	      "cl", // 21
53	      "hd", // 22
54	      "ao", // 23
55	      "bm"  // 24
56	  );
