58	  public static Layer parse(LottieComposition composition) {
59	    Rect bounds = composition.getBounds();
60	    return new Layer(
61	        Collections.<ContentModel>emptyList(), composition, "__container", -1,
62	        Layer.LayerType.PRE_COMP, -1, null, Collections.<Mask>emptyList(),
63	        new AnimatableTransform(), 0, 0, 0, 0, 0,
64	        bounds.width(), bounds.height(), null, null, Collections.<Keyframe<Float>>emptyList(),
65	        Layer.MatteType.NONE, null, false, null, null,
66	        LBlendMode.NORMAL);
67	  }
68	
69	  private static final JsonReader.Options TEXT_NAMES = JsonReader.Options.of(
70	      "d",
71	      "a"
72	  );
73	
74	  private static final JsonReader.Options EFFECTS_NAMES = JsonReader.Options.of(
75	      "ty",
76	      "nm"
77	  );
78	
79	  public static Layer parse(JsonReader reader, LottieComposition composition) throws IOException {
80	    // This should always be set by After Effects. However, if somebody wants to minify
81	    // and optimize their json, the name isn't critical for most cases so it can be removed.
82	    String layerName = "UNSET";
83	    Layer.LayerType layerType = null;
84	    String refId = null;
85	    long layerId = 0;
86	    int solidWidth = 0;
87	    int solidHeight = 0;
88	    int solidColor = 0;
89	    float preCompWidth = 0;
90	    float preCompHeight = 0;
91	    long parentId = -1;
92	    float timeStretch = 1f;
93	    float startFrame = 0f;
94	    float inFrame = 0f;
95	    float outFrame = 0f;
96	    String cl = null;
97	    boolean hidden = false;
98	    BlurEffect blurEffect = null;
99	    DropShadowEffect dropShadowEffect = null;
100	    boolean autoOrient = false;
101	
102	    Layer.MatteType matteType = Layer.MatteType.NONE;
103	    LBlendMode blendMode = LBlendMode.NORMAL;
104	    AnimatableTransform transform = null;
105	    AnimatableTextFrame text = null;
106	    AnimatableTextProperties textProperties = null;
107	    AnimatableFloatValue timeRemapping = null;
108	
109	    List<Mask> masks = new ArrayList<>();
110	    List<ContentModel> shapes = new ArrayList<>();
111	
112	    reader.beginObject();
113	    while (reader.hasNext()) {
114	      switch (reader.selectName(NAMES)) {
115	        case 0:
116	          layerName = reader.nextString();
117	          break;
118	        case 1:
119	          layerId = reader.nextInt();
120	          break;
121	        case 2:
122	          refId = reader.nextString();
123	          break;
124	        case 3:
125	          int layerTypeInt = reader.nextInt();
126	          if (layerTypeInt < Layer.LayerType.UNKNOWN.ordinal()) {
127	            layerType = Layer.LayerType.values()[layerTypeInt];
128	          } else {
129	            layerType = Layer.LayerType.UNKNOWN;
130	          }
131	          break;
132	        case 4:
133	          parentId = reader.nextInt();
134	          break;
135	        case 5:
136	          solidWidth = (int) (reader.nextInt() * Utils.dpScale());
137	          break;
138	        case 6:
139	          solidHeight = (int) (reader.nextInt() * Utils.dpScale());
140	          break;
141	        case 7:
142	          solidColor = Color.parseColor(reader.nextString());
143	          break;
144	        case 8:
145	          transform = AnimatableTransformParser.parse(reader, composition);
146	          break;
147	        case 9:
148	          int matteTypeIndex = reader.nextInt();
149	          if (matteTypeIndex >= Layer.MatteType.values().length) {
150	            composition.addWarning("Unsupported matte type: " + matteTypeIndex);
151	            break;
152	          }
153	          matteType = Layer.MatteType.values()[matteTypeIndex];
154	          switch (matteType) {
155	            case LUMA:
156	              composition.addWarning("Unsupported matte type: Luma");
157	              break;
158	            case LUMA_INVERTED:
159	              composition.addWarning("Unsupported matte type: Luma Inverted");
160	              break;
161	          }
162	          composition.incrementMatteOrMaskCount(1);
163	          break;
164	        case 10:
165	          reader.beginArray();
166	          while (reader.hasNext()) {
167	            masks.add(MaskParser.parse(reader, composition));
168	          }
169	          composition.incrementMatteOrMaskCount(masks.size());
170	          reader.endArray();
171	          break;
172	        case 11:
173	          reader.beginArray();
174	          while (reader.hasNext()) {
175	            ContentModel shape = ContentModelParser.parse(reader, composition);
176	            if (shape != null) {
177	              shapes.add(shape);
178	            }
179	          }
180	          reader.endArray();
181	          break;
182	        case 12: // Text data
183	          reader.beginObject();
184	          while (reader.hasNext()) {
185	            switch (reader.selectName(TEXT_NAMES)) {
186	              case 0: // "d", Text contents
187	                text = AnimatableValueParser.parseDocumentData(reader, composition);
188	                break;
189	              case 1: // "a", Text ranges with custom animations and style
190	                reader.beginArray();
191	                if (reader.hasNext()) {
192	                  textProperties = AnimatableTextPropertiesParser.parse(reader, composition);
193	                }
194	                // TODO support more than one text range
195	                while (reader.hasNext()) {
196	                  reader.skipValue();
197	                }
198	                reader.endArray();
199	                break;
200	              // TODO support Text follow path and Text alignment
201	              default:
202	                reader.skipName();
203	                reader.skipValue();
204	            }
205	          }
206	          reader.endObject();
207	          break;
208	        case 13:
209	          reader.beginArray();
210	          List<String> effectNames = new ArrayList<>();
211	          while (reader.hasNext()) {
212	            reader.beginObject();
213	            while (reader.hasNext()) {
214	              switch (reader.selectName(EFFECTS_NAMES)) {
215	                case 0:
216	                  int type = reader.nextInt();
217	                  if (type == 29) {
218	                    blurEffect = BlurEffectParser.parse(reader, composition);
219	                  } else if (type == 25) {
220	                    dropShadowEffect = new DropShadowEffectParser().parse(reader, composition);
221	                  }
222	                  break;
223	                case 1:
224	                  String effectName = reader.nextString();
225	                  effectNames.add(effectName);
226	                  break;
227	                default:
228	                  reader.skipName();
229	                  reader.skipValue();
230	
231	              }
232	            }
233	            reader.endObject();
234	          }
235	          reader.endArray();
236	          composition.addWarning("Lottie doesn't support layer effects. If you are using them for " +
237	              " fills, strokes, trim paths etc. then try adding them directly as contents " +
238	              " in your shape. Found: " + effectNames);
239	          break;
240	        case 14:
241	          timeStretch = (float) reader.nextDouble();
242	          break;
243	        case 15:
244	          startFrame = (float) reader.nextDouble();
245	          break;
246	        case 16:
247	          preCompWidth = (float) (reader.nextDouble() * Utils.dpScale());
248	          break;
249	        case 17:
250	          preCompHeight = (float) (reader.nextDouble() * Utils.dpScale());
251	          break;
252	        case 18:
253	          inFrame = (float) reader.nextDouble();
254	          break;
255	        case 19:
256	          outFrame = (float) reader.nextDouble();
257	          break;
258	        case 20:
259	          timeRemapping = AnimatableValueParser.parseFloat(reader, composition, false);
260	          break;
261	        case 21:
262	          cl = reader.nextString();
263	          break;
264	        case 22:
265	          hidden = reader.nextBoolean();
266	          break;
267	        case 23:
268	          autoOrient = reader.nextInt() == 1;
269	          break;
270	        case 24:
271	          int blendModeIndex = reader.nextInt();
272	          if (blendModeIndex >= LBlendMode.values().length) {
273	            composition.addWarning("Unsupported Blend Mode: " + blendModeIndex);
274	            blendMode = LBlendMode.NORMAL;
275	            break;
276	          }
277	          blendMode = LBlendMode.values()[blendModeIndex];
278	          break;
279	        default:
280	          reader.skipName();
281	          reader.skipValue();
282	      }
283	    }
284	    reader.endObject();
285	
286	    List<Keyframe<Float>> inOutKeyframes = new ArrayList<>();
287	    // Before the in frame
288	    if (inFrame > 0) {
289	      Keyframe<Float> preKeyframe = new Keyframe<>(composition, 0f, 0f, null, 0f, inFrame);
290	      inOutKeyframes.add(preKeyframe);
291	    }
292	
293	    // The + 1 is because the animation should be visible on the out frame itself.
294	    outFrame = (outFrame > 0 ? outFrame : composition.getEndFrame());
295	    Keyframe<Float> visibleKeyframe =
296	        new Keyframe<>(composition, 1f, 1f, null, inFrame, outFrame);
297	    inOutKeyframes.add(visibleKeyframe);
298	
299	    Keyframe<Float> outKeyframe = new Keyframe<>(
300	        composition, 0f, 0f, null, outFrame, Float.MAX_VALUE);
301	    inOutKeyframes.add(outKeyframe);
302	
303	    if (layerName.endsWith(".ai") || "ai".equals(cl)) {
304	      composition.addWarning("Convert your Illustrator layers to shape layers.");
305	    }
306	
307	    if (autoOrient) {
308	      if (transform == null) {
309	        transform = new AnimatableTransform();
310	      }
311	      transform.setAutoOrient(autoOrient);
312	    }
313	    return new Layer(shapes, composition, layerName, layerId, layerType, parentId, refId,
314	        masks, transform, solidWidth, solidHeight, solidColor, timeStretch, startFrame,
315	        preCompWidth, preCompHeight, text, textProperties, inOutKeyframes, matteType,
316	        timeRemapping, hidden, blurEffect, dropShadowEffect, blendMode);
317	  }
318	}
