156	  private static <T> Keyframe<T> parseMultiDimensionalKeyframe(LottieComposition composition, JsonReader reader,
157	      float scale, ValueParser<T> valueParser) throws IOException {
158	    PointF cp1 = null;
159	    PointF cp2 = null;
160	
161	    PointF xCp1 = null;
162	    PointF xCp2 = null;
163	    PointF yCp1 = null;
164	    PointF yCp2 = null;
165	
166	    float startFrame = 0;
167	    T startValue = null;
168	    T endValue = null;
169	    boolean hold = false;
170	    Interpolator interpolator = null;
171	    Interpolator xInterpolator = null;
172	    Interpolator yInterpolator = null;
173	
174	    // Only used by PathKeyframe
175	    PointF pathCp1 = null;
176	    PointF pathCp2 = null;
177	
178	    reader.beginObject();
179	    while (reader.hasNext()) {
180	      switch (reader.selectName(NAMES)) {
181	        case 0: // t
182	          startFrame = (float) reader.nextDouble();
183	          break;
184	        case 1: // s
185	          startValue = valueParser.parse(reader, scale);
186	          break;
187	        case 2: // e
188	          endValue = valueParser.parse(reader, scale);
189	          break;
190	        case 3: // o
191	          if (reader.peek() == JsonReader.Token.BEGIN_OBJECT) {
192	            reader.beginObject();
193	            float xCp1x = 0f;
194	            float xCp1y = 0f;
195	            float yCp1x = 0f;
196	            float yCp1y = 0f;
197	            while (reader.hasNext()) {
198	              switch (reader.selectName(INTERPOLATOR_NAMES)) {
199	                case 0: // x
200	                  if (reader.peek() == JsonReader.Token.NUMBER) {
201	                    xCp1x = (float) reader.nextDouble();
202	                    yCp1x = xCp1x;
203	                  } else {
204	                    reader.beginArray();
205	                    xCp1x = (float) reader.nextDouble();
206	                    if (reader.peek() == JsonReader.Token.NUMBER) {
207	                      yCp1x = (float) reader.nextDouble();
208	                    } else {
209	                      yCp1x = xCp1x;
210	                    }
211	                    reader.endArray();
212	                  }
213	                  break;
214	                case 1: // y
215	                  if (reader.peek() == JsonReader.Token.NUMBER) {
216	                    xCp1y = (float) reader.nextDouble();
217	                    yCp1y = xCp1y;
218	                  } else {
219	                    reader.beginArray();
220	                    xCp1y = (float) reader.nextDouble();
221	                    if (reader.peek() == JsonReader.Token.NUMBER) {
222	                      yCp1y = (float) reader.nextDouble();
223	                    } else {
224	                      yCp1y = xCp1y;
225	                    }
226	                    reader.endArray();
227	                  }
228	                  break;
229	                default:
230	                  reader.skipValue();
231	              }
232	            }
233	            xCp1 = new PointF(xCp1x, xCp1y);
234	            yCp1 = new PointF(yCp1x, yCp1y);
235	            reader.endObject();
236	          } else {
237	            cp1 = JsonUtils.jsonToPoint(reader, scale);
238	          }
239	          break;
240	        case 4: // i
241	          if (reader.peek() == JsonReader.Token.BEGIN_OBJECT) {
242	            reader.beginObject();
243	            float xCp2x = 0f;
244	            float xCp2y = 0f;
245	            float yCp2x = 0f;
246	            float yCp2y = 0f;
247	            while (reader.hasNext()) {
248	              switch (reader.selectName(INTERPOLATOR_NAMES)) {
249	                case 0: // x
250	                  if (reader.peek() == JsonReader.Token.NUMBER) {
251	                    xCp2x = (float) reader.nextDouble();
252	                    yCp2x = xCp2x;
253	                  } else {
254	                    reader.beginArray();
255	                    xCp2x = (float) reader.nextDouble();
256	                    if (reader.peek() == JsonReader.Token.NUMBER) {
257	                      yCp2x = (float) reader.nextDouble();
258	                    } else {
259	                      yCp2x = xCp2x;
260	                    }
261	                    reader.endArray();
262	                  }
263	                  break;
264	                case 1: // y
265	                  if (reader.peek() == JsonReader.Token.NUMBER) {
266	                    xCp2y = (float) reader.nextDouble();
267	                    yCp2y = xCp2y;
268	                  } else {
269	                    reader.beginArray();
270	                    xCp2y = (float) reader.nextDouble();
271	                    if (reader.peek() == JsonReader.Token.NUMBER) {
272	                      yCp2y = (float) reader.nextDouble();
273	                    } else {
274	                      yCp2y = xCp2y;
275	                    }
276	                    reader.endArray();
277	                  }
278	                  break;
279	                default:
280	                  reader.skipValue();
281	              }
282	            }
283	            xCp2 = new PointF(xCp2x, xCp2y);
284	            yCp2 = new PointF(yCp2x, yCp2y);
285	            reader.endObject();
286	          } else {
287	            cp2 = JsonUtils.jsonToPoint(reader, scale);
288	          }
289	          break;
290	        case 5: // h
291	          hold = reader.nextInt() == 1;
292	          break;
293	        case 6: // to
294	          pathCp1 = JsonUtils.jsonToPoint(reader, scale);
295	          break;
296	        case 7: // ti
297	          pathCp2 = JsonUtils.jsonToPoint(reader, scale);
298	          break;
299	        default:
300	          reader.skipValue();
301	      }
302	    }
303	    reader.endObject();
304	
305	    if (hold) {
306	      endValue = startValue;
307	      // TODO: create a HoldInterpolator so progress changes don't invalidate.
308	      interpolator = LINEAR_INTERPOLATOR;
309	    } else if (cp1 != null && cp2 != null) {
310	      interpolator = interpolatorFor(cp1, cp2);
311	    } else if (xCp1 != null && yCp1 != null && xCp2 != null && yCp2 != null) {
312	      xInterpolator = interpolatorFor(xCp1, xCp2);
313	      yInterpolator = interpolatorFor(yCp1, yCp2);
314	    } else {
315	      interpolator = LINEAR_INTERPOLATOR;
316	    }
317	
318	    Keyframe<T> keyframe;
319	    if (xInterpolator != null && yInterpolator != null) {
320	      keyframe = new Keyframe<>(composition, startValue, endValue, xInterpolator, yInterpolator, startFrame, null);
321	    } else {
322	      keyframe = new Keyframe<>(composition, startValue, endValue, interpolator, startFrame, null);
323	    }
324	
325	    keyframe.pathCp1 = pathCp1;
326	    keyframe.pathCp2 = pathCp2;
327	    return keyframe;
328	  }
329	
330	  private static Interpolator interpolatorFor(PointF cp1, PointF cp2) {
331	    Interpolator interpolator = null;
332	    cp1.x = MiscUtils.clamp(cp1.x, -1f, 1f);
333	    cp1.y = MiscUtils.clamp(cp1.y, -MAX_CP_VALUE, MAX_CP_VALUE);
334	    cp2.x = MiscUtils.clamp(cp2.x, -1f, 1f);
335	    cp2.y = MiscUtils.clamp(cp2.y, -MAX_CP_VALUE, MAX_CP_VALUE);
336	    int hash = Utils.hashFor(cp1.x, cp1.y, cp2.x, cp2.y);
337	    WeakReference<Interpolator> interpolatorRef = L.getDisablePathInterpolatorCache() ? null : getInterpolator(hash);
338	    if (interpolatorRef != null) {
339	      interpolator = interpolatorRef.get();
340	    }
341	    if (interpolatorRef == null || interpolator == null) {
342	      try {
343	        interpolator = PathInterpolatorCompat.create(cp1.x, cp1.y, cp2.x, cp2.y);
344	      } catch (IllegalArgumentException e) {
345	        if ("The Path cannot loop back on itself.".equals(e.getMessage())) {
346	          // If a control point extends beyond the previous/next point then it will cause the value of the interpolator to no
347	          // longer monotonously increase. This clips the control point bounds to prevent that from happening.
348	          // NOTE: this will make the rendered animation behave slightly differently than the original.
349	          interpolator = PathInterpolatorCompat.create(Math.min(cp1.x, 1f), cp1.y, Math.max(cp2.x, 0f), cp2.y);
350	        } else {
351	          // We failed to create the interpolator. Fall back to linear.
352	          interpolator = new LinearInterpolator();
353	        }
354	      }
355	      if (!L.getDisablePathInterpolatorCache()) {
356	        try {
357	          putInterpolator(hash, new WeakReference<>(interpolator));
358	        } catch (ArrayIndexOutOfBoundsException e) {
359	          // It is not clear why but SparseArrayCompat sometimes fails with this:
360	          //     https://github.com/airbnb/lottie-android/issues/452
361	          // Because this is not a critical operation, we can safely just ignore it.
362	          // I was unable to repro this to attempt a proper fix.
363	        }
364	      }
365	    }
366	    return interpolator;
367	  }
