369	  private static <T> Keyframe<T> parseStaticValue(JsonReader reader,
370	      float scale, ValueParser<T> valueParser) throws IOException {
371	    T value = valueParser.parse(reader, scale);
372	    return new Keyframe<>(value);
373	  }
