  AnimatableTextRangeSelector rangeSelector = textProperties.rangeSelector;
  if (rangeSelector != null) {
    if (rangeSelector.start != null) {
      textRangeStartAnimation = rangeSelector.start.createAnimation();
      textRangeStartAnimation.addUpdateListener(this);
      addAnimation(textRangeStartAnimation);
    }
    if (rangeSelector.end != null) {
      textRangeEndAnimation = rangeSelector.end.createAnimation();
      textRangeEndAnimation.addUpdateListener(this);
