82	  protected enum RenderStrategy {
83	      /** No-op: simply render to the underlying canvas directly. */
84	      DIRECT,
85	      /** Use Canvas.saveLayer() and compose using Canvas.restore(). */
86	      SAVE_LAYER,
87	      /** Render everything onto an off-screen bitmap and then draw it onto the main canvas */
88	      BITMAP,
89	      /** Render into a RenderNode's display-list and then draw the render node. (Hardware accelerated) */
90	      RENDER_NODE
91	  }
