127	  // Android doesn't render shadows on arbitrary bitmaps correctly. Instead, if we're using
128	  // render-to-bitmap, we have to draw them manually. To do so, we need an additional bitmap, an
129	  // associated canvas, paint, and some other data, which we define as members to avoid
130	  // reallocation. (And also because in the render-node case, we won't need them.)
131	  @Nullable private Bitmap shadowBitmap;
132	  @Nullable private Bitmap shadowMaskBitmap;
133	  @Nullable private Canvas shadowBitmapCanvas;
134	  @Nullable private Canvas shadowMaskBitmapCanvas;
135	  @Nullable private LPaint shadowPaint;
136	  @Nullable private BlurMaskFilter shadowBlurFilter;
137	  private float lastShadowBlurRadius = 0.0f;
138	
139	  // For RenderStrategy.RENDER_NODE:
140	  @Nullable private RenderNode renderNode; // Render node with the initial contents of the layer
141	  @Nullable private RenderNode shadowRenderNode; // Render node for the shadow
142	  @Nullable private DropShadow lastRenderNodeShadow;
