349	  public void finish() {
350	    if (parentCanvas == null || op == null || preExistingTransform == null || targetRect == null) {
351	      throw new IllegalStateException("OffscreenBitmap: finish() call without matching start()");
352	    }
353	
354	    switch (currentStrategy) {
355	      case DIRECT:
356	        parentCanvas.restore();
357	        break;
358	
359	      case SAVE_LAYER:
360	        parentCanvas.restore();
361	        break;
362	
363	      case BITMAP:
364	        if (bitmap == null) {
365	          throw new IllegalStateException("Bitmap is not ready; should've been initialized at start() time");
366	        }
367	
368	        if (op.hasShadow()) {
369	          // Composing the shadow first and then the content like this will be incorrect in the
370	          // presence of op.blendMode. However, that is not used at the moment, so this
371	          // optimization is safe. (Otherwise, we'd have to have another bitmap here for the
372	          // intermediate result.)
373	          renderBitmapShadow(parentCanvas, op.shadow);
374	        }
375	
376	        if (bitmapSrcRect == null) bitmapSrcRect = new Rect();
377	        bitmapSrcRect.set(0, 0, (int)(targetRect.width() * preExistingTransform[Matrix.MSCALE_X]), (int)(targetRect.height() * preExistingTransform[Matrix.MSCALE_Y]));
378	        parentCanvas.drawBitmap(bitmap, bitmapSrcRect, targetRect, composePaint);
379	        break;
380	
381	      case RENDER_NODE:
382	        if (renderNode == null) {
383	          throw new IllegalStateException("RenderNode is not ready; should've been initialized at start() time");
384	        }
385	
386	        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.Q) {
387	          throw new IllegalStateException("RenderNode not supported but we chose it as render strategy");
388	        }
389	
390	        parentCanvas.save();
391	        parentCanvas.scale(1.0f / preExistingTransform[Matrix.MSCALE_X], 1.0f / preExistingTransform[Matrix.MSCALE_Y]);
392	        renderNode.endRecording();
393	        if (op.hasShadow()) {
394	          // Composing the shadow first and then the content like this will be incorrect in the
395	          // presence of op.blendMode. However, that is not used at the moment, so this
396	          // optimization is safe. (Otherwise, we'd have to have another render node here for the
397	          // intermediate result.)
398	          renderHardwareShadow(parentCanvas, op.shadow);
399	        }
400	        parentCanvas.drawRenderNode(renderNode);
401	        parentCanvas.restore();
402	        break;
403	    }
404	
405	    parentCanvas = null;
406	  }
