408	  private RectF calculateRectIncludingShadow(RectF rect, DropShadow shadow) {
409	    if (rectIncludingShadow == null) rectIncludingShadow = new RectF();
410	    if (tmpRect == null) tmpRect = new RectF();
411	    rectIncludingShadow.set(rect);
412	    rectIncludingShadow.offsetTo(rect.left + shadow.getDx(), rect.top + shadow.getDy());
413	    rectIncludingShadow.inset(-shadow.getRadius(), -shadow.getRadius());
414	    tmpRect.set(rect);
415	    rectIncludingShadow.union(tmpRect);
416	    return rectIncludingShadow;
417	  }
418	
419	  /** Renders a shadow (only the shadow) of this.bitmap to the provided canvas. */
420	  private void renderBitmapShadow(Canvas targetCanvas, DropShadow shadow) {
421	    if (targetRect == null || bitmap == null) {
422	      throw new IllegalStateException("Cannot render to bitmap outside a start()/finish() block");
423	    }
424	
425	    // This is an expanded rect that encompasses the full extent of the shadow.
426	    RectF rectIncludingShadow = calculateRectIncludingShadow(targetRect, shadow);
427	    if (intRectIncludingShadow == null) intRectIncludingShadow = new Rect();
428	    intRectIncludingShadow.set(
429	        (int)Math.floor(rectIncludingShadow.left),
430	        (int)Math.floor(rectIncludingShadow.top),
431	        (int)Math.ceil(rectIncludingShadow.right),
432	        (int)Math.ceil(rectIncludingShadow.bottom)
433	    );
434	    float pixelScaleX = preExistingTransform != null ? preExistingTransform[Matrix.MSCALE_X] : 1.0f;
435	    float pixelScaleY = preExistingTransform != null ? preExistingTransform[Matrix.MSCALE_Y] : 1.0f;
436	    if (scaledRectIncludingShadow == null) scaledRectIncludingShadow = new RectF();
437	    scaledRectIncludingShadow.set(
438	        rectIncludingShadow.left * pixelScaleX,
439	        rectIncludingShadow.top * pixelScaleY,
440	        rectIncludingShadow.right * pixelScaleX,
441	        rectIncludingShadow.bottom * pixelScaleY
442	    );
443	
444	    if (shadowBitmapSrcRect == null) shadowBitmapSrcRect = new Rect();
445	    shadowBitmapSrcRect.set(0, 0, (int)Math.round(scaledRectIncludingShadow.width()), (int)Math.round(scaledRectIncludingShadow.height()));
446	    if (needNewBitmap(shadowBitmap, scaledRectIncludingShadow)) {
447	      if (shadowBitmap != null) {
448	        deallocateBitmap(shadowBitmap);
449	      }
450	      if (shadowMaskBitmap != null) {
451	        deallocateBitmap(shadowMaskBitmap);
452	      }
453	
454	      shadowBitmap = allocateBitmap(scaledRectIncludingShadow, Bitmap.Config.ARGB_8888);
455	      shadowMaskBitmap = allocateBitmap(scaledRectIncludingShadow, Bitmap.Config.ALPHA_8);
456	      shadowBitmapCanvas = new Canvas(shadowBitmap);
457	      shadowMaskBitmapCanvas = new Canvas(shadowMaskBitmap);
458	    } else {
459	      if (shadowBitmapCanvas == null || shadowMaskBitmapCanvas == null || clearPaint == null) {
460	        throw new IllegalStateException("If needNewBitmap() returns true, we should have a canvas and bitmap ready");
461	      }
462	      shadowBitmapCanvas.drawRect(shadowBitmapSrcRect, clearPaint);
463	      shadowMaskBitmapCanvas.drawRect(shadowBitmapSrcRect, clearPaint);
464	    }
465	
466	    if (shadowMaskBitmap == null) throw new IllegalStateException("Expected to have allocated a shadow mask bitmap");
467	    
468	    if (shadowPaint == null) {
469	      shadowPaint = new LPaint(Paint.ANTI_ALIAS_FLAG);
470	    }
471	
472	    // This is the offset of targetRect inside rectIncludingShadow
473	    float offsetX = targetRect.left - rectIncludingShadow.left;
474	    float offsetY = targetRect.top - rectIncludingShadow.top;
475	
476	    // Draw the image onto the mask layer first. Since the mask layer is ALPHA_8, this discards color information.
477	    // Align it so that when drawn in the end, it originates at targetRect.x, targetRect.y
478	    // the int casts are very important here - they save us from some slow path for non-integer coords
479	    shadowMaskBitmapCanvas.drawBitmap(bitmap, (int)Math.round(offsetX * pixelScaleX), (int)Math.round(offsetY * pixelScaleY), null);
480	
481	    // Prepare the shadow paint. This is the paint that will perform a blur and a tint of the mask
482	    if (shadowBlurFilter == null || lastShadowBlurRadius != shadow.getRadius()) {
483	      float scaledRadius = shadow.getRadius() * (pixelScaleX + pixelScaleY) / 2.0f;
484	      if (scaledRadius > 0) {
485	        shadowBlurFilter = new BlurMaskFilter(scaledRadius, BlurMaskFilter.Blur.NORMAL);
486	      } else {
487	        shadowBlurFilter = null;
488	      }
489	
490	      lastShadowBlurRadius = shadow.getRadius();
491	    }
492	    shadowPaint.setColor(shadow.getColor());
493	    if (shadow.getRadius() > 0.0f) {
494	      shadowPaint.setMaskFilter(shadowBlurFilter);
495	    } else {
496	      shadowPaint.setMaskFilter(null);
497	    }
498	    shadowPaint.setFilterBitmap(true);
499	
500	    // Draw the mask onto our shadowBitmap with the shadowPaint. This bitmap now contains the final
501	    // look of the shadow, correctly positioned inside a rectIncludingShadow-sized area
502	    // the int casts are very important here - they save us from some slow path for non-integer coords
503	    shadowBitmapCanvas.drawBitmap(shadowMaskBitmap, (int)Math.round(shadow.getDx() * pixelScaleX), (int)Math.round(shadow.getDy() * pixelScaleY), shadowPaint);
504	
505	    // Now blit the result onto the final canvas. It might be tempting to skip shadowBitmap and draw the mask
506	    // directly onto the canvas with shadowPaint, but this breaks the blur, since Paint.setMaskFilter() is not
507	    // supported on hardware canvases.
508	    targetCanvas.drawBitmap(shadowBitmap, shadowBitmapSrcRect, intRectIncludingShadow, composePaint);
509	  }
