511	  /** Renders a shadow (only the shadow) of this.renderNode to the provided canvas. */
512	  private void renderHardwareShadow(Canvas targetCanvas, DropShadow shadow) {
513	    if (renderNode == null || shadowRenderNode == null) {
514	      throw new IllegalStateException("Cannot render to render node outside a start()/finish() block");
515	    }
516	
517	    if (Build.VERSION.SDK_INT < Build.VERSION_CODES.S) {
518	      throw new RuntimeException("RenderEffect is not supported on API level <31");
519	    }
520	
521	    // The render node canvas is in the pre-pixelscale space, so we have to scale the shadow parameters
522	    // by the pixel scale
523	    float pixelScaleX = preExistingTransform != null ? preExistingTransform[Matrix.MSCALE_X] : 1.0f;
524	    float pixelScaleY = preExistingTransform != null ? preExistingTransform[Matrix.MSCALE_Y] : 1.0f;
525	
526	    if (lastRenderNodeShadow == null || !shadow.sameAs(lastRenderNodeShadow)) {
527	      RenderEffect effect = RenderEffect.createColorFilterEffect(new PorterDuffColorFilter(shadow.getColor(), PorterDuff.Mode.SRC_IN));
528	      if (shadow.getRadius() > 0.0f) {
529	        float scaledRadius = shadow.getRadius() * (pixelScaleX + pixelScaleY) / 2.0f;
530	        effect = RenderEffect.createBlurEffect(scaledRadius, scaledRadius, effect, Shader.TileMode.CLAMP);
531	      }
532	      shadowRenderNode.setRenderEffect(effect);
533	      lastRenderNodeShadow = shadow;
534	    }
535	
536	    RectF rectIncludingShadow = calculateRectIncludingShadow(targetRect, shadow);
537	    RectF scaledRectIncludingShadow = new RectF(
538	        rectIncludingShadow.left * pixelScaleX,
539	        rectIncludingShadow.top * pixelScaleY,
540	        rectIncludingShadow.right * pixelScaleX,
541	        rectIncludingShadow.bottom * pixelScaleY
542	    );
543	
544	    shadowRenderNode.setPosition(0, 0, (int)scaledRectIncludingShadow.width(), (int)scaledRectIncludingShadow.height());
545	    Canvas shadowCanvas = shadowRenderNode.beginRecording((int)scaledRectIncludingShadow.width(), (int)scaledRectIncludingShadow.height());
546	    // Offset so that the image starts at the top left, and then offset by shadow displacement
547	    shadowCanvas.translate(-scaledRectIncludingShadow.left + shadow.getDx() * pixelScaleX, -scaledRectIncludingShadow.top + shadow.getDy() * pixelScaleY);
548	    shadowCanvas.drawRenderNode(renderNode);
549	    shadowRenderNode.endRecording();
550	
551	    targetCanvas.save();
552	    targetCanvas.translate(scaledRectIncludingShadow.left, scaledRectIncludingShadow.top);
553	    targetCanvas.drawRenderNode(shadowRenderNode);
554	    targetCanvas.restore();
555	  }
556	
557	  /**
558	   * Whether calling finish() will decrement the save count of the [Canvas] returned by [start()].
559	   */
560	  public boolean finishDecrementsCanvasSaveCount() {
561	    // endRecording() will decrement the save count of the Canvas returned by beginRecording()
